const resp = $json;
const raw = (resp.textResponse || resp.response || '').trim();
if (!raw) throw new Error('AnythingLLM no respondió: ' + JSON.stringify(resp).substring(0,200));

// Limpiar backticks y bloques de código
let limpio = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
// Quitar bloque <think> si existe
const thinkMatch = limpio.match(/<\/think>\s*([\s\S]*)/);
if (thinkMatch) limpio = thinkMatch[1].trim();

let parsed;
try {
  parsed = JSON.parse(limpio);
} catch(e) {
  const match = limpio.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); }
    catch(e2) { throw new Error('JSON inválido de ALLM: ' + limpio.substring(0,300)); }
  } else {
    throw new Error('Sin JSON en respuesta ALLM: ' + limpio.substring(0,300));
  }
}

const action = parsed.action || '';
const payload = parsed.payload || {};
const razon = parsed.razon || '';

if (!action) throw new Error('ALLM no generó acción válida: ' + JSON.stringify(parsed));

// Inyectar secret
return [{ json: { action, payload, razon, secret: 'allm-n8n-2026', instruccion_original: $('Webhook').first().json.body?.instruccion || '' } }];

const gw_resp = $json;
const instruccion = $('Parsear Accion ALLM').first().json.instruccion_original || '';
const accion = $('Parsear Accion ALLM').first().json.action || '';
const razon = $('Parsear Accion ALLM').first().json.razon || '';
const datos = gw_resp.data || gw_resp;

let resumen = '';
if (accion === 'list_workflows') {
  const wfs = datos.workflows || [];
  resumen = `Encontré ${wfs.length} workflows:\n` + wfs.map(w => `  ${w.active ? '✅' : '⭕'} ${w.name} (${w.id})`).join('\n');
} else if (accion === 'get_workflow') {
  resumen = `Workflow: ${datos.name}\nEstado: ${datos.active ? 'Activo' : 'Inactivo'}\nNodos: ${datos.nodeCount || '?'}\n${(datos.nodes||[]).map(n=>'  • '+n.name+' ('+n.type+')').join('\n')}`;
} else if (accion === 'execute_workflow') {
  resumen = `Ejecución iniciada. ${datos.success ? 'Exitosa.' : 'Con errores: '+JSON.stringify(datos)}`;
} else if (accion === 'create_workflow') {
  resumen = `Workflow creado: ${datos.name || datos.id || 'ID: '+JSON.stringify(datos).substring(0,100)}`;
} else if (accion === 'update_workflow') {
  resumen = `Workflow actualizado: ${datos.name || JSON.stringify(datos).substring(0,100)}`;
} else if (['activate_workflow','deactivate_workflow'].includes(accion)) {
  resumen = `${accion === 'activate_workflow' ? 'Activado' : 'Desactivado'}: ${datos.name || datos.id}`;
} else if (accion === 'delete_workflow') {
  resumen = `Workflow eliminado.`;
} else {
  resumen = JSON.stringify(datos, null, 2).substring(0, 500);
}

return [{ json: {
  success: true,
  instruccion: instruccion,
  accion_ejecutada: accion,
  razon: razon,
  resultado: resumen,
  datos_completos: datos
}}];
